INSERT IGNORE INTO dart_disclosure (
    corp_code, stock_code, corp_name,
    receipt_no, report_name, disclosure_date,
    submitter, disclosure_url, is_important
) VALUES (
    #{corpCode}, #{stockCode}, #{corpName},
    #{receiptNo}, #{reportName}, #{disclosureDate},
    #{submitter}, #{disclosureUrl}, #{isImportant}
)
